"""Editorial analysis. Source quotations live separately and are never paraphrased here."""
STEPS=[
 dict(id='define',title='Define the work, information, and scope',owner='Mission owner · information owner · security, privacy, records, and acquisition staff',rmf='Prepare',original='Your step 1, with a scope and ownership check added.',
 summary='Start with the agency’s work, not a provider’s control package. Describe what people will do, which information will move, and what harm could follow from disclosure, alteration, loss, or misuse. Identify the officials who own the information and accept risk.',
 actions=['Map creation, collection, processing, storage, sharing, and disposal. Include account details, logs, metadata, exports, integrations, and information sent to other providers. State permitted and prohibited uses.', 'Identify applicable legal, privacy, records, accessibility, acquisition, and agency requirements. Security categorization alone does not answer all of these questions.', 'Decide whether this use falls within M-24-15 §III and current FedRAMP scope guidance. Record the applicable inclusion or exclusion, the specific offering and deployment, and who approved the determination. Resolve uncertainty with agency officials and FedRAMP.'],
 alignment='FISMA protects both agency information and the systems described in the statute. M-24-15 makes scope depend on handling federal information on an agency’s behalf, with listed exclusions. A service’s commercial status does not answer that scope question.',
 concern=('Do not turn “external” into an exemption','A boundary decision is not a ruling that FISMA, A-130, or FedRAMP cannot apply. The proposal works without asserting that every commercial cloud is outside the statutory system definition. Out-of-scope services still need the protections applicable to the agency’s information and use.'),
 quotes=['f14-dual','omb-scope'],
 fields=[('mission','Work and limits','What task, users, and uses are allowed? What is prohibited?'),('flows','Information and flows','Information types, origins, recipients, processing, storage, logs, exports, retention, and disposal. Identify the responsible information owner.'),('scope','Scope and applicable obligations','Record the FedRAMP scope provision, offering/version, inclusion or exclusion rationale, other obligations, reviewer, and date.')]),
 dict(id='categorize',title='Categorize information and the agency system',owner='Information owner · system owner · authorizing official or delegate',rmf='Categorize',original='Your steps 1–2, keeping the information and system decisions distinct.',
 summary='Assess confidentiality, integrity, and availability separately for each information type. Then categorize the agency system that will support the work. Record the harm behind each rating.',
 actions=['Use FIPS 199 and relevant SP 800-60 information-type guidance. Consider mission impact, people affected, aggregated information, and system processing needs. Public information can still require strong integrity and availability protection.', 'Derive the system’s security category from its information types, taking the highest impact for each objective. FIPS 200 then uses the system impact level in baseline selection.', 'Document and obtain the required agency review of the categorization. Revisit it if the design, information, or use changes. Assess privacy and other risks alongside the security category.'],
 alignment='FISMA §3554(a)(2) connects harm assessment to protection levels and implementation. FIPS 199 supplies separate information-type and system categories; FIPS 200 connects the system category to control selection.',
 concern=('A certification class is not a FIPS category','Do not choose the agency’s impact level to match an available service or its FedRAMP certification class. Current FedRAMP guidance distinguishes assurance classes from the agency’s security categorization.'),
 quotes=['f14-implement','f199-info','f199-system','f199-highwater','fed-class'],
 fields=[('information-cia','Information-type ratings','For each type: confidentiality / integrity / availability impact; concrete harm; rationale; approving official.'),('system-cia','System category and approval','System name, impact by objective, overall impact, aggregation considerations, approval/date, and separate privacy risks.')]),
 dict(id='design',title='Set the boundary and allocate controls',owner='System owner · security/privacy architects · common control providers',rmf='Prepare + Select',original='Your step 2, with architecture and shared responsibilities made explicit.',
 summary='Describe a real agency system: its people, procedures, technology, and dependencies. Select and tailor controls for that system. Allocate each protection to the agency, a common control provider, an external service, or a combination.',
 actions=['Draw the agency authorization boundary, provider certification boundary, and information exchanges. Explain which components are included, which services are external, and how the agency depends on them. Boundaries can differ without creating a gap in responsibility.', 'Select the applicable baseline from SP 800-53B, use the current SP 800-53 catalog, and document tailoring, parameters, supplemental controls, and privacy requirements. FIPS 200’s older citation to SP 800-53 is read with its instruction to use the current publication as amended.', 'Define required capabilities before comparing providers: identity, access, logging, recovery, data protection, incident coordination, and other needs. Record the customer work necessary to use provider capabilities. Revisit the design when a service cannot support a necessary capability.'],
 alignment='RMF §2.5 defines the boundary around management and responsibilities. Task S-3 allocates controls to system elements and the environment. SA-9 supplies external-service oversight and monitoring requirements within this wider control set.',
 concern=('Neither the provider nor an empty container is the agency system','Do not copy a provider’s entire system into an agency SSP. Do not invent a nominal enclosing system just to avoid describing the actual use. For a simple SaaS use, the agency’s accounts, configurations, information handling, personnel, and procedures still need a meaningful boundary and authorization path.'),
 quotes=['rmf-boundary','f200-select','baseline-modern','rmf-allocate','sa9-control'],
 fields=[('boundary','Boundary and dependencies','Describe or link the diagram: agency resources, provider offering, interfaces, inherited services, and exclusions with reasons.'),('allocation','Control allocation and tailoring','For each requirement/control: rationale, parameter, agency/provider/shared owner, implementation, evidence needed, and monitoring owner. Record SA-9 oversight and monitoring assignments.')]),
 dict(id='service-review',title='Reuse FedRAMP evidence and decide whether the service fits',owner='System owner · assessors · security/privacy staff · acquisition team',rmf='Select + risk assessment',original='Your step 3, with the statutory presumption of adequacy applied.',
 summary='Compare candidate services against the agency’s needs. Reuse the FedRAMP package for the provider’s assessed work. Spend agency effort on whether the specific offering, configuration, dependencies, and proposed use meet the mission and protection needs.',
 actions=['Confirm the exact certified or authorized offering, boundary, included features, status, applicable assurance information, and ongoing evidence. Check whether the planned deployment is covered. Use current FedRAMP guidance for the assurance evidence; do not invent a certification-class-to-FIPS-impact equivalence. A related product name or marketplace entry is not enough.', 'Review secure configuration guidance, responsibility allocations, assessment findings, ongoing reports, inherited services, and constraints. Distinguish provider evidence, agency implementation evidence, and unanswered questions.', 'Use the presumption of adequacy. Ask clarifying questions. If added provider requirements or information are needed, record the demonstrable need and use the required agency determination and FedRAMP notification procedures. Collaborate with FedRAMP on package conflicts; document a wholly or substantially deficient package determination where applicable.', 'Select a service that supports the required capabilities, or revise the architecture or use. Track unresolved issues and acquisition conditions. Selection is not permission to begin processing information.'],
 alignment='44 USC 3613(a)(3) requires reuse to the extent practicable. Section 3613(e) presumes the assessment adequate while preserving FISMA duties and demonstrable additional needs. M-24-15 §IV and current Agency Use rules implement that balance.',
 concern=('Do not recreate the provider assessment under SA-9','Selecting controls for the agency system does not justify sending the provider a new agency checklist. Separate a customer-side configuration or integration need from an additional provider security requirement. Use the current FedRAMP process for the latter; a routine preference is not automatically a demonstrable need.'),
 quotes=['act-reuse','act-presume','omb-presume','fed-extra'],
 fields=[('service','Selected offering and evidence','Provider/service/version/deployment, package identifier and date, status/class or impact basis as applicable, features and inherited services covered, reviewers, and evidence links.'),('fit','Fit, gaps, and reuse','Required capability → provider evidence → agency configuration/work → residual gap/risk. Identify stale or missing evidence.'),('additional','Additional provider requirements, if any','Distinguish clarification from added requirements. State demonstrable need, determining official, notification/reference, package conflicts, and resolution. Enter “none” when appropriate.')]),
 dict(id='agree',title='Perform and sign a Cloud Service Authorization',owner='Agency CSA signing official · system owner · acquisition, security, and privacy staff',rmf='Proposed FedRAMP CSA process · supports Select and Implement',original='Your revised step 4: a distinct, signed CSA under a new FedRAMP process, separate from the agency system ATO.',
 summary='Under this proposal, the agency follows a new FedRAMP-specific process to authorize a cloud service for use by its agency information system. The result is a signed Cloud Service Authorization (CSA). The agency references that CSA from its system documentation for SA-9, SA-4, and other applicable controls.',
 actions=['Use the FedRAMP-defined CSA procedure to review the service, reuse provider assessment evidence, resolve agency-specific requirements, and make a service-level risk decision for the identified agency system. This is an agency CSA, distinct from the provider’s FedRAMP authorization or certification.', 'Document the service and approved information/use, required protections, provider and agency responsibilities, configuration and integration conditions, evidence relied on, residual risks, monitoring duties, and review or termination triggers. Identify the signing official and authority required by the new process.', 'Set agreements for security/privacy, incidents, recovery, evidence access, information exchanges, records, retention/deletion, and exit. Reference the signed CSA by identifier and version from SA-9 external-service documentation, SA-4 acquisition documentation, and other applicable controls such as CA-3. Each control entry should still explain its own implementation and responsibilities.', 'Issue a distinct signed CSA decision and retain its supporting record. Link it to the agency system and its ATO package. For a new system, the CSA can precede the completed system ATO, with operational use contingent on that ATO. For an already authorized system, perform the CSA within its lifecycle and determine whether the proposed use requires an ATO update or other agency risk decision.'],
 alignment='The Act’s process, template, and reuse authorities and M-24-15 provide a basis for proposing this procedure. A-130 and SA-4, SA-9, and CA-3 support the agreements, responsibilities, and evidence it would document. The cited materials do not themselves establish this distinct signed agency CSA; FedRAMP would need to adopt and define it through the applicable governance process.',
 concern=('FedRAMP must define the new decision, not just its name','The new process needs a defined scope, signing authority, decision standard, required evidence, signature and record requirements, monitoring and revocation rules, and relationship to the system ATO. It must preserve the statutory presumption of adequacy and agency FISMA duties. SA-9 and SA-4 document the CSA’s implementation; they do not independently create the CSA process.'),
 quotes=['a16-contracts','sa4-contract','ca3-exchange'],
 fields=[('agreements','Agreements and control references','Contract/agreement reference → requirement → responsible party → evidence/remedy. Map the CSA identifier and version to SA-9, SA-4, CA-3, and other applicable agency-system control entries.'),('draft-decision','CSA decision and signed record','Status (draft, approved, denied, or deferred); CSA ID/version; FedRAMP CSA procedure/version; agency system ID; service and approved information/use; requirements, responsibilities, evidence, residual risk, conditions and monitoring; signing official/authority, signature/date and signed-record location; linked system ATO. This worksheet does not sign the CSA.')]),
 dict(id='implement',title='Configure, integrate, and assess the agency’s implementation',owner='System owner · implementers · control assessors',rmf='Implement + Assess',original='Your step 5, with implementation evidence separated from provider evidence.',
 summary='Build or configure the agency’s use, implement customer responsibilities, and assess that implementation. Reuse provider evidence where it applies. Check that the combined arrangement works, not merely that each party has documents.',
 actions=['Implement the approved design, agency controls, shared controls, configuration settings, access rules, training, and operating procedures. Record actual implementation in the agency security/privacy plans and link SA-9, SA-4, and other applicable entries to the signed CSA. Reconcile implementation changes with CSA conditions before operational use.', 'Test relevant integrations and agency responsibilities: account lifecycle, privileged access, information sharing, log delivery, incident coordination, recovery, and exit capabilities. Confirm that claimed inherited capabilities are available in the selected service and deployment.', 'Prepare assessment results, remediation plans, and residual-risk analysis. Link provider findings that affect agency risk to the agency decision; do not duplicate every provider POA&M as if it were agency work.', 'Revisit the design or service selection if the combined controls are inadequate. Use only an appropriately approved test or pilot arrangement before operational authorization.'],
 alignment='FISMA requires implementation and periodic evaluation. A-130 requires contractor oversight. NIST’s reuse guidance still requires consideration of integration risk, and current FedRAMP guidance tells agencies to test their implementation.',
 concern=('A signed CSA does not authorize an unfinished agency system','The CSA is a distinct service decision under the proposed FedRAMP process. The agency still has to implement and assess the system that uses the service. Operational use must be covered by the agency system’s ATO; a CSA alone does not supply that authorization. A limited pilot has its own conditions.'),
 quotes=['a16-oversight','rmf-integrate','fed-configure'],
 fields=[('implementation','Agency implementation and assessment','Implemented settings/procedures, evidence links, assessor/date, provider evidence reused, inherited capabilities checked, and integration tests/results.'),('residual','Findings and risk response','Finding → affected mission/information → owner → mitigation or acceptance → due date. Link provider remediation and record any agency compensating actions.')]),
 dict(id='authorize',title='Authorize the agency information system under FISMA',owner='Agency authorizing official',rmf='Authorize',original='Your step 5: the agency system ATO remains a separate decision under FISMA, supported by the signed CSA records.',
 summary='The agency authorizing official makes the ATO decision for the federal information system as a whole. The system authorization package incorporates the signed CSA for each cloud service, along with evidence for agency controls, integrations, and the rest of the system.',
 actions=['Complete the agency system assessment and authorization package under the applicable FISMA, OMB, and NIST processes. Identify the system boundary, mission and information, all relevant controls, integration evidence, residual risks, and the signed CSA records being relied on.', 'Issue or update the agency system ATO through agency procedures. Reference the CSA identifiers and versions and ensure their conditions are reflected in the system design, SA-9, SA-4, other applicable controls, and monitoring plan. The CSA and ATO remain distinct signed decisions with different scopes.', 'Keep existing terminology clear. M-24-15 and SP 800-37 also describe an ATU reuse route, quoted below for comparison. This proposal uses a system ATO plus a new CSA; it does not rename an ATU as a CSA or claim that the existing ATU provisions already establish the new process.', 'Submit the agency ATO letter and supplementary information to FedRAMP as currently required. Any CSA-specific submission or registration requirement would need to be established in the new process. If system risk is unacceptable, resolve the issue, restrict the use, or deny the ATO even if a service has a CSA.'],
 alignment='A-130 assigns formal system authorization to senior federal officials. The FedRAMP Act preserves agency FISMA responsibility and requires submission of the agency ATO based on FedRAMP authorization. The proposed CSA supplies a separate service decision and evidence within that system lifecycle; it does not discharge the system-level duties.',
 concern=('Separate decisions should reuse the same evidence','The CSA addresses the cloud service’s approved use, requirements, and responsibilities. The ATO addresses the agency system as a whole, including integration and combined risk. FedRAMP would need to make the distinction operational so agencies can reference CSA work in the ATO package without repeating the provider assessment or issuing an ATO for the provider’s offering.'),
 quotes=['a16-ato','omb24-atu','rmf-atu','rmf-atu-condition','rmf-atu-decision','act-notify','fed-notify'],
 fields=[('decision','Agency system ATO and CSA references','System/package ID; ATO official, decision/date and signed-record location; approved scope, information, configuration, residual risk and conditions; linked CSA IDs/versions and SA-9/SA-4/other control references; review triggers. Record denial, deferral, or the treatment of a change to an existing ATO.'),('notification','ATO submission and proposed CSA reporting','Date/reference and agency ATO letter/supplementary information supplied to FedRAMP, or why not applicable. Separately identify any CSA reporting that the new procedure would require; do not assume it replaces the ATO submission.')]),
 dict(id='monitor',title='Monitor both, respond to change, and plan exit',owner='System owner · monitoring staff · authorizing official · service contacts',rmf='Monitor + disposal',original='Your step 6, with feedback, change response, and exit added.',
 summary='Use FedRAMP’s ongoing service evidence in the agency’s continuous monitoring program. Monitor the agency’s configuration, accounts, integrations, and procedures too. Use both streams to maintain the CSA’s conditions and inform the agency system’s ongoing ATO decision.',
 actions=['Specify evidence sources, review cadence, owners, escalation paths, and durable contacts. Include relevant inherited service evidence. Review provider reports and findings for their effect on the agency’s authorized use.', 'Monitor customer controls, configuration drift, logs, account changes, privacy/records handling, incidents, and agency remediation. Record what the agency accepted, changed, or escalated in response to service evidence.', 'Reassess when information, mission, deployment, features, integrations, provider posture, certification status, or threats change. Notify FedRAMP and the provider when required; decide whether to continue, restrict, suspend, or end use. Under the proposed process, record any CSA revision or revocation and its effect on the system ATO.', 'Plan export, retention, deletion, account closure, key handling, transition, and evidence of completion before exit. Disposal is part of the information lifecycle, not a task left to the provider’s default retention policy.'],
 alignment='SA-9 requires ongoing external-provider monitoring and leaves risk with the authorizing official. M-24-15 supplies a shared monitoring framework; current FedRAMP guidance expressly says it does not replace agency monitoring.',
 concern=('Two evidence streams must not become two disconnected programs','FedRAMP monitoring is not a transfer of the agency’s risk responsibility. Equally, agency monitoring should not recreate the provider’s program or demand advance approval for every service change. Monitor the provider’s change process and the effects on the agency’s use, following current FedRAMP procedures.'),
 quotes=['sa9-risk','omb-monitor','omb-agility','fed-monitor'],
 fields=[('monitoring','Monitoring plan','Evidence/report → review frequency → reviewer → trigger/threshold → action/official. Include provider and agency sources, inherited services, and continuity of contacts.'),('change-exit','Change, incident, and exit plan','Triggers for re-review, restrictions or suspension; incident coordination/notification; export/retention/deletion; account/key closure; transition owner; completion evidence.')])

]

REVIEW=[
 ('1','Begin with information and use','Aligned. Add ownership, information flows, non-security obligations, and a FedRAMP scope determination.','define'),
 ('2','Categorize the agency system and tailor controls','Aligned. Derive the category from information and mission harm; define a real boundary and allocate responsibilities.','categorize'),
 ('3','Evaluate external services using FedRAMP evidence','Aligned with conditions. Presume provider assessment adequate; document fit and customer work without repeating the assessment.','service-review'),
 ('4','Perform a Cloud Service Authorization through a new FedRAMP process','Proposed new procedure. Agencies would issue a distinct signed CSA for cloud services used by their agency information system, document the applicable requirements, and reference the CSA from SA-9, SA-4, and other controls. The system ATO remains separate.','agree'),
 ('5','Implement, assess, and authorize the agency system','Aligned. Complete the system’s FISMA assessment and ATO, using signed CSAs as supporting decisions and assessing agency implementation and integrations.','implement'),
 ('6','Monitor the service and agency system','Aligned if connected. Feed FedRAMP evidence into agency monitoring, ongoing risk acceptance, and change/exit decisions.','monitor')]
